-- RBAC Phase 1a (loop unit p1a-migration): give roles a tenant owner, a preset
-- lineage and a colour, give every grant a scope, and seed the seven preset
-- roles with the full fine-grained capability catalogue from the frontend SSOT.
--
-- The coarse legacy permissions (contacts:read etc.) and the existing
-- RequirePermission gates are untouched — the fine keys coexist beside them,
-- so no running deployment loses access through this migration.
--
-- RLS design, the part that is easy to get wrong:
-- `roles` must NOT go through enable_tenant_rls(). That procedure writes
-- `tenant_id = current_tenant_id() OR is_system_context()`, which hides every
-- row with tenant_id IS NULL — and all seven presets are exactly those rows.
-- The result would be an empty capability set for everyone including admin,
-- indistinguishable from "no permissions granted".
-- Read and write policy are split instead of using one USING clause: DELETE
-- only ever consults USING, so a single permissive policy that lets a tenant
-- read the presets would also let it delete them.
--   read  : own tenant + system presets
--   write : own tenant only (presets are seed data, immutable for the app role)

SET LOCAL row_security = off;

BEGIN;

-- 1) roles: tenant ownership (NULL = system preset), preset lineage, UI colour.
ALTER TABLE roles
    ADD COLUMN tenant_id UUID NULL REFERENCES tenants(id) ON DELETE CASCADE,
    ADD COLUMN based_on  UUID NULL REFERENCES roles(id)   ON DELETE SET NULL,
    ADD COLUMN color     VARCHAR(40) NOT NULL DEFAULT '';

-- 2) Role names are unique per tenant, not globally: two tenants may both name
--    a custom role "Buchhaltung". COALESCE maps the presets onto a fixed
--    sentinel so they keep colliding with each other.
--    This expression must stay byte-identical to the ON CONFLICT clause of the
--    generated seed below, otherwise Postgres finds no arbiter index.
DROP INDEX idx_roles_name;
CREATE UNIQUE INDEX idx_roles_tenant_name
    ON roles (COALESCE(tenant_id, '00000000-0000-0000-0000-000000000000'::uuid), name);

-- 3) role_permissions: the data scope a grant is valid for. Default 'all' so
--    every pre-existing grant keeps exactly today's behaviour.
ALTER TABLE role_permissions
    ADD COLUMN scope VARCHAR(8) NOT NULL DEFAULT 'all'
        CONSTRAINT role_permissions_scope_check CHECK (scope IN ('own', 'team', 'all'));

-- 4) RLS on roles.
ALTER TABLE roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE roles FORCE ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation_read ON roles
    FOR SELECT
    USING (tenant_id IS NULL OR tenant_id = current_tenant_id() OR is_system_context());

CREATE POLICY tenant_isolation_write ON roles
    FOR ALL
    USING (tenant_id = current_tenant_id() OR is_system_context())
    WITH CHECK (tenant_id = current_tenant_id() OR is_system_context());

-- 5) RLS on role_permissions, derived through the owning role. Same asymmetry:
--    the presets' grants are readable by every tenant, writable by none.
ALTER TABLE role_permissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE role_permissions FORCE ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation_read ON role_permissions
    FOR SELECT
    USING (EXISTS (
        SELECT 1 FROM roles r
        WHERE r.id = role_permissions.role_id
          AND (r.tenant_id IS NULL OR r.tenant_id = current_tenant_id() OR is_system_context())
    ));

CREATE POLICY tenant_isolation_write ON role_permissions
    FOR ALL
    USING (EXISTS (
        SELECT 1 FROM roles r
        WHERE r.id = role_permissions.role_id
          AND (r.tenant_id = current_tenant_id() OR is_system_context())
    ))
    WITH CHECK (EXISTS (
        SELECT 1 FROM roles r
        WHERE r.id = role_permissions.role_id
          AND (r.tenant_id = current_tenant_id() OR is_system_context())
    ));

-- 6) Seed. Everything below this line is the verbatim output of
--    `cd desktop && npx tsx --tsconfig tsconfig.web.json scripts/gen-rbac-seed.mjs`
--    — regenerate it there, do not hand-edit it here.

-- ============================================================
-- Generated by desktop/scripts/gen-rbac-seed.mjs — do not hand-edit.
-- Source of truth: mocks/data/rbac.ts (ROLE_DEFS) + config/capability-catalog.ts.
-- ============================================================

-- (a) permissions
-- 282 keys: level-1 module:view visibility for every module +
-- every fine capability key from capability-catalog.ts.
ON CONFLICT (name) DO NOTHING;

-- (b) the 4 missing preset roles + color backfill on the 3 existing ones
-- Preset roles migration 000002 never seeded. tenant_id stays NULL — system
-- preset, visible to every tenant via the roles RLS policy.
ON CONFLICT (COALESCE(tenant_id, '00000000-0000-0000-0000-000000000000'::uuid), name) DO NOTHING;

-- Backfill color on the 3 presets migration 000002 already created.
UPDATE roles SET color = 'hsl(0 72% 51%)' WHERE name = 'admin' AND tenant_id IS NULL;
UPDATE roles SET color = 'hsl(217 91% 60%)' WHERE name = 'manager' AND tenant_id IS NULL;
UPDATE roles SET color = 'hsl(142 71% 45%)' WHERE name = 'member' AND tenant_id IS NULL;

